```json
{
  "pasos": [
    {
      "id": "s1",
      "op": "search_catalog",
      "args": {
        "query": "notebook",
        "category": "notebooks",
        "max_price": 1678990,
        "attributes": {
          "ram_gb": {
            "min": 16
          }
        }
      }
    },
    {
      "id": "s2",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.0.id",
        "limit": 3
      }
    },
    {
      "id": "s3",
      "op": "get_product",
      "args": {
        "id": "$s1.1.id"
      }
    },
    {
      "id": "s4",
      "op": "get_reviews",
      "args": {
        "product_id": "$s1.1.id",
        "limit": 3
      }
    },
    {
      "id": "s5",
      "op": "compare_products",
      "args": {
        "ids": [
          "$s1.0.id",
          "$s1.1.id"
        ]
      }
    },
    {
      "id": "s6",
      "op": "respond",
      "plantilla": "Encontré {cantidad} notebooks con 16 GB o más de RAM dentro de tu presupuesto. Te recomiendo estos dos:\n\n1. {nombre1} <<rec:{id1}>> - ${precio1} CLP\n   Evaluación: {rating1}/5\n   Resumen de reseñas: {resenas1}\n\n2. {nombre2} <<rec:{id2}>> - ${precio2} CLP\n   Evaluación: {rating2}/5\n   Resumen de reseñas: {resenas2}\n\nComparación <<cmp:{id1},{id2}>>:\n- Más barato: {mas_barato}\n- Mejor evaluado: {mejor_evaluado}\n\nAmbos son excelentes para programación y contenedores. ¿Necesitas más detalles de alguno?",
      "vars": {
        "cantidad": "$s1.length",
        "nombre1": "$s1.0.name",
        "id1": "$s1.0.id",
        "precio1": "$s1.0.price_clp",
        "rating1": "$s1.0.avg_rating",
        "resenas1": "$s2",
        "nombre2": "$s3.name",
        "id2": "$s3.id",
        "precio2": "$s3.price_clp",
        "rating2": "$s3.avg_rating",
        "resenas2": "$s4",
        "mas_barato": "$s5.mas_barato",
        "mejor_evaluado": "$s5.mejor_evaluado"
      }
    }
  ]
}
